dtsPropsFor.Button:
/** Element or component to render as; use 'a' or a router Link for navigation. The element's own props (href, onClick, disabled, type…) pass through. @default 'button' */
  as?: React.ElementType;
  /** Visual register: chrome = the primary action (.v2-cta, a matte face in a 1px foil rim) · ghost = .v2-cta.is-ghost · foil = the seam-red wax-seal .btn-foil · ink = .btn-foil.is-ink, for the cream register only · link = the quiet mono .ds-btn-link. @default 'chrome' */
  variant?: 'chrome' | 'ghost' | 'foil' | 'ink' | 'link';
  /** Append a decorative → glyph (aria-hidden). @default false */
  arrow?: boolean;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Card:
/** Render the foil-edged panel (.rfx-panel-foil, which fills one bare inner div) instead of the default leather panel (.rfx-panel). @default false */
  foil?: boolean;
  className?: string;
  style?: React.CSSProperties;
  /** Placed as direct children: the panel's raking-light catch sits beneath them. Any div attribute also passes through. */
  children?: React.ReactNode;

dtsPropsFor.DiamondMark:
/** Glyph set upright inside the tilted diamond. @default 'PA' */
  label?: string;
  /** The 1/1 face via .is-gold. The name is historical: the material is the matte ember (var(--ember)). @default false */
  gold?: boolean;
  /** Square edge length in px, applied to width and height. @default 48 */
  size?: number;
  className?: string;
  style?: React.CSSProperties;

dtsPropsFor.Hairline:
/** The bone fade tuned for the dark stage (.hairline-stage); the default (.hairline) is the machined-brown fade for the cream field. @default false */
  stage?: boolean;
  className?: string;
  style?: React.CSSProperties;

dtsPropsFor.Input:
/** Optional mono field label (.mono-label) rendered above the input and wired to it by id (a generated id when none is passed). */
  label?: string;
  id?: string;
  value?: string;
  defaultValue?: string;
  placeholder?: string;
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  /** Any other input attribute (type, name, required, aria-*) passes through to the .rfx-input element. */
  className?: string;

dtsPropsFor.Kicker:
/** Reserved no-op: .rfx-skick always draws its leading rule and no no-rule modifier ships yet. @default true */
  rule?: boolean;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.ScoutRow:
/** The fact's name, in the mono key column. */
  label: string;
  /** Optional source tier; when set, the provenance dot trails the value. */
  tier?: 'official' | 'reputable' | 'secondhand' | 'unverified';
  /** The sourced value. Wrap a run of rows in the .rfx-scout container. */
  children: React.ReactNode;
  className?: string;

dtsPropsFor.SearchField:
/** Called when Escape is pressed while the field is non-empty. */
  onClear?: () => void;
  /** Class applied to the outer field shell (the InputGroup). */
  groupClassName?: string;
  /** Controlled through the standard input props; any other input attribute passes through. */
  value?: string;
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  placeholder?: string;
  'aria-label'?: string;
  className?: string;

dtsPropsFor.SegmentedToggle:
/** Segments: bare strings (value = label) or { value, label } pairs. */
  options: Array<string | { value: string; label: string }>;
  /** The selected option value (controlled). */
  value?: string;
  /** Called with the option value when a segment is clicked. */
  onChange?: (value: string) => void;
  /** Class merged onto the outer shell. */
  className?: string;

dtsPropsFor.SourceBadge:
/** Confidence tier: drives the dot color and the default wording. @default 'official' */
  tier?: 'official' | 'reputable' | 'secondhand' | 'unverified' | 'pitcher-own-words' | 'coach-observed' | 'community-firsthand';
  /** Show the actual source name in place of the tier's wording. */
  label?: string;
  /** Show the "≈ approx" pill: a real figure that is rounded or era-bound. @default false */
  approximate?: boolean;
  className?: string;

dtsPropsFor.Stamp:
/** Ink and box ride currentColor: set color on the stamp or a parent. */
  style?: React.CSSProperties;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Tag:
/** Element to render as; use 'button' for an interactive filter chip. @default 'span' */
  as?: React.ElementType;
  /** On-state; maps to aria-pressed, the chip's only on-state hook. Leave unset for a plain label. */
  active?: boolean;
  /** Decorative glyph before the label, kept a direct child (mark it aria-hidden). */
  glyph?: React.ReactNode;
  onClick?: (event: React.MouseEvent) => void;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.BrandMark:
/** sm = masthead, md = default and footer, lg = hero. @default 'md' */
  size?: 'sm' | 'md' | 'lg';
  /** Show the athletic PITCH ATLAS wordmark beside the mark. @default true */
  wordmark?: boolean;
  className?: string;

dtsPropsFor.ConfidenceDot:
/** The claim's tier; color and wording come from the canonical confidence metadata. */
  confidence: 'official-data' | 'pitcher-own-words' | 'coach-observed' | 'reputable-analysis' | 'secondhand-attributed' | 'community-firsthand' | 'unverified';
  /** Show the tier's wording beside the dot. @default true */
  withLabel?: boolean;
  className?: string;

dtsPropsFor.PitchSpecimenCard:
/** A filed pitch record from PITCHES (window.PitchAtlas.PITCHES). Never hand-built: a specimen the atlas never filed is a fabrication. Specimen 00 renders as the ember 1/1. */
  entry: PitchAtlasEntry;
  /** Position in a set; staggers the reveal. @default 0 */
  index?: number;
  /** Card max width in px; the card sizes itself from its container, so give it a full-width block. @default 360 */
  maxWidth?: number;
  /** Mount the live WebGL foil (the hero card only). @default false */
  foil?: boolean;
  /** Paint the grip face eagerly (the page's hero card). @default false */
  priority?: boolean;
  /** Route-specific timing and framing for the real grip clip. sourceOverride passes the file and poster together, so the still and the loop show the same moment. */
  clipPresentation?: { playback?: 'loop' | 'once'; start?: number; sourceOverride?: { mp4: string; webm: string; poster: string; alt: string }; mediaClassName?: string };
  className?: string;

dtsPropsFor.Select:
/** Radix Select root. Compose inside it: SelectTrigger (size 'sm' | 'default') › SelectValue, then SelectContent (position 'item-aligned' | 'popper') › SelectItem (value), with SelectGroup, SelectLabel and SelectSeparator for grouping. The list portals to <body>. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  name?: string;
  disabled?: boolean;
  required?: boolean;
  children?: React.ReactNode;

dtsPropsFor.Dialog:
/** Radix Dialog root. Compose inside it: DialogTrigger (asChild around a Button), then DialogContent (showCloseButton, default true) › DialogHeader › DialogTitle + DialogDescription, and DialogFooter with DialogClose. The content portals to <body>. */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  modal?: boolean;
  children?: React.ReactNode;

dtsPropsFor.Tooltip:
/** Radix Tooltip root; must sit inside TooltipProvider (delayDuration defaults to 0). Compose TooltipTrigger (asChild around the trigger) and TooltipContent (side, sideOffset). The content portals to <body>. */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  delayDuration?: number;
  children?: React.ReactNode;

dtsPropsFor.Toaster:
/** sonner's Toaster, preset to the dark theme and the popover tokens. Render it once; fire toasts with toast() / toast.success() (window.PitchAtlas.toast). */
  position?: 'top-left' | 'top-center' | 'top-right' | 'bottom-left' | 'bottom-center' | 'bottom-right';
  expand?: boolean;
  closeButton?: boolean;
  richColors?: boolean;
  duration?: number;
  visibleToasts?: number;
  className?: string;

dtsPropsFor.BallStage:
/** One filed record from PITCHES. Its motion.spinAxis sets the turn; its gripModel seats the hand. */
  entry: (typeof PITCHES)[number];
  /** Seat the solved hand on the pitch's filed contacts. @default false */
  grip?: boolean;
  /** Which face of the hold turns to the camera. @default entry.canonical.gripModel.defaultView */
  view?: 'top' | 'side' | 'thumb';
  /** @default 'right' */
  handedness?: 'right' | 'left';
  /** 'stage' on the void, 'paper' on the cream field: the finger tone and the fallback drawing follow it. @default 'paper' */
  surface?: 'paper' | 'stage';
  /** Draw the spin-axis and Magnus vectors (the physics presentation; no page mounts it today). @default false */
  vectors?: boolean;
  /** Turn the hold toward the camera for study. @default false */
  faceGrip?: boolean;
  /** Turn slowly on the pitch's own spin axis; stops under reduced motion and off screen. @default true */
  autoSpin?: boolean;
  /** Drag to turn. Off inside a card window, where the card itself is the link. @default true */
  interactive?: boolean;
  /** Camera distance: pull back on square or card-shaped canvases so the whole hand stays in frame. */
  distance?: number;
  /** Mark one contact by its label. */
  activeContact?: string;
  className?: string;

dtsPropsFor.SeamSchematic:
/** Draw the pitch's spin axis, dashed, or as a dot for a gyro pitch. @default true */
showAxis?: boolean;
/** Draw the red lacing on the seam. @default true */
showStitches?: boolean;
/** Name each finger over its contact. @default true */
showLabels?: boolean;
/** The pitch's render-space spin axis (a record's motion.spinAxis). @default the four-seam's near-horizontal backspin */
spinAxis?: { x: number; y: number; z: number };
/** Gyro pitch (the slider): the axis points at the viewer and reads as a dot. @default false */
gyro?: boolean;
/** Grip contacts (a record's canonical.gripModel.contacts) drawn as solved finger silhouettes. */
grip?: (typeof PITCHES)[number]['canonical']['gripModel']['contacts'];
/** Which face of the hold the drawing turns toward the viewer. */
view?: 'top' | 'side' | 'thumb';
/** The contacts the view is solved against when the hand itself is not drawn. */
referenceContacts?: (typeof PITCHES)[number]['canonical']['gripModel']['contacts'];
/** @default 'right' */
handedness?: 'right' | 'left';
/** 'stage' on the void, 'paper' on the cream field: sets the finger tone. @default 'paper' */
surface?: 'paper' | 'stage';
/** The accessible name. An empty string marks a decorative use and hides the drawing from assistive tech. @default a four-seam description */
title?: string;
className?: string;
